async delete({ businessID, offeringId }: DeleteOfferingDTO): Promise<DeleteOfferingResponse> {
        OfferingService.logger.log(`Attempting to delete offering: ${offeringId} for ${businessID}`);
        const offeringDbModels = await this.InfluxService.getLatestOfferingConfig({ businessID, offeringId });
        try {
            const { data: serviceIds } = await this.servicesService.findAllServicesWithofferingId({
                businessID,
                offeringId,
            });
            if (serviceIds.length) {
                throw new ConflictException(
                    `Cannot delete offering when they are attached to services, remove services from offerings before deleting. Current serviceIds using the offering: ${serviceIds.reduce(
                        (acc, { serviceId }) => {
                            acc += `${serviceId}   `;
                            return acc;
                        },
                        ''
                    )} `
                );
            }
        } catch (error) {
            if (error instanceof NotFoundException) {
                // Ignore
            } else {
                throw error;
            }
        }
        try {
            const { data: customers } = await this.customerService.findAll({ businessID });
            const referencingCustomers = customers.filter((c) => c.offeringId === offeringId);
            if (referencingCustomers.length) {
                throw new ConflictException(
                    `Cannot delete offering when it is referenced by customers. Remove offering from customers before deleting. Current customerIds using the offering: ${referencingCustomers
                        .map((c) => c.customerId)
                        .join(', ')}`
                );
            }
        } catch (error) {
            if (error instanceof NotFoundException) {
                // Ignore
            } else {
                throw error;
            }
        }
        if (offeringDbModels.length) {
            const { loadPoints } = this.InfluxService;
            const entity = OfferingPackageEntity.dbModelToEntity(offeringDbModels[0]);
            entity.softDelete = true;
            entity.businessID = businessID;
            const points = OfferingPackageEntity.transformer(entity, this.InfluxService);
            OfferingService.logger.log('Points to delete', points);

            await loadPoints(`${process.env.STAGE}-config`, `paigo`, points);

            return { message: 'Deleted Offering', offeringId: entity.offeringId };
        } else {
            throw new NotFoundException(`No offering documents matching ID offeringId:${offeringId}`);
        }
    }

